SELECT owner_name, schema_name, object_type, grantee_name, grantee_type, privilege_type, admin_option FROM (SELECT owner_name, NVL(schema_name, '') AS schema_name, object_type, grantee_name, grantee_type, privilege_type, admin_option FROM svv_default_privileges UNION ALL SELECT u.usename AS owner_name, '' AS schema_name, 'FUNCTION' AS object_type, 'public' AS grantee_name, 'public' AS grantee_type, 'EXECUTE' AS privilege_type, false AS admin_option FROM pg_user u WHERE NOT EXISTS (SELECT 1 FROM pg_default_acl d WHERE d.defacluser = u.usesysid AND d.defaclnamespace = 0 AND d.defaclobjtype = 'f')) AS defaults WHERE owner_name = :owner AND schema_name = :schema AND grantee_name = :grantee ORDER BY owner_name, schema_name, object_type, grantee_type, grantee_name, privilege_type;
